const D = { energy: .58, scale: 1, density: .55, speed: 1, fall: .55, hue: 22, x: .5, y: .5, style: 'ashfall', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- An ash plain, days after. Not the eruption — the aftermath: a grey pyroclastic desert
// under a sky that has not cleared, ash still falling out of it like snow, lahar channels cut
// down through the fresh fall to the old surface, and a fissure somewhere off the horizon
// throwing a dull red on the underside of the cloud. Everything is one material.
// The fall never stops and the deck never clears, so the frame can never settle. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function fr(i){ return hsh((i*7+13)|0, (i*31+5)|0); }
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function fbm4(x,y){ return .46*vn(x,y)+.26*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9)+.11*vn(x*8.11+1.3,y*8.11-4.7); }
// ridged noise: the sharp-crested fabric of a wind-worked ash surface
function rdg(x,y){ return 1-Math.abs(vn(x,y)*2-1); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), fal = cl(P.fall,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', ember = sty==='ember', ink = sty==='ink', thm = sty==='thermal';

// ---- palette: a grey world. The default is deliberately COLD and desaturated — the warm
// volcanic read already exists as world.volcano; this is the ash, not the fire. ----
let skyT, skyH, ashD, ashL, fissC, hazeC;
if (bp)        { skyT=[214,74,13]; skyH=[204,52,28];  ashD=[200,60,16]; ashL=[188,40,74]; fissC=[188,54,96]; hazeC=[201,46,32]; }
else if (ember){ skyT=[Hh+330,54,13]; skyH=[Hh-8,66,34]; ashD=[Hh+340,34,12]; ashL=[Hh+6,26,58]; fissC=[Hh-4,92,99]; hazeC=[Hh-2,44,32]; }
else if (ink)  { skyT=[Hh+150,5,50]; skyH=[Hh+150,4,72]; ashD=[Hh+150,6,15]; ashL=[Hh+150,4,62]; fissC=[Hh+150,7,34]; hazeC=[Hh+150,4,66]; }
else if (thm)  { skyT=[248,74,16]; skyH=[286,52,38];  ashD=[258,56,18]; ashL=[302,42,68]; fissC=[44,90,99];  hazeC=[292,44,40]; }
else           { skyT=[Hh+206,14,24]; skyH=[Hh+30,10,52]; ashD=[Hh+220,9,17]; ashL=[Hh+34,7,68]; fissC=[Hh-8,80,80]; hazeC=[Hh+26,8,50]; }

const hzn = cl(P.y,.24,.76), hy = hzn*height;
const sc = cl(P.scale,.5,2.2);

// ---- perpetual drift: the ash blanket is advected, the deck rolls, neither returns ----
if (S.dz == null) S.dz = 0;
if (S.lt == null || K.t < S.lt) S.lt = K.t;
const dt = cl(K.t - S.lt, 0, .1); S.lt = K.t;
S.dz += dt * P.speed * (.075 + .095*K.intensity) * (.82 + .18*Math.sin(tt*.043));
const dz = S.dz;

const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(64, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const cT = hsv(skyT[0], skyT[1]/100, skyT[2]/100);
const cH = hsv(skyH[0], skyH[1]/100, skyH[2]/100);
const cAd = hsv(ashD[0], ashD[1]/100, ashD[2]/100);
const cAl = hsv(ashL[0], ashL[1]/100, ashL[2]/100);
const cF = hsv(fissC[0], fissC[1]/100, fissC[2]/100);
const cHz = hsv(hazeC[0], hazeC[1]/100, hazeC[2]/100);

// the fissure glow off the horizon: breathes on incommensurate rates, never pulses to beat
const fissX = cl(P.x + .22*Math.sin(tt*.0139) + .08*Math.sin(tt*.0361+1.9), -.1, 1.1);
const fissB = (.30+en*.85) * (.72 + .16*Math.sin(tt*.109) + .09*Math.sin(tt*.263+.7)
                                  + .07*Math.sin(tt*.041) + K.swell*.10 + A.bass*.16);
// the deck rolls on two incommensurate rates
const dk1 = tt*.055, dk2 = tt*.034;
const sunOcc = .42 + .30*fbm(tt*.017, 3.3);      // how much light gets through the deck at all

for (let j=0;j<BH;j++){
  const ny = (j+.5)/BH;
  for (let i=0;i<BW;i++){
    const nx = (i+.5)/BW;
    let r,g2,b2;
    if (ny < hzn){
      // ================= the deck that will not clear =================
      const sv = Math.pow(cl(ny/hzn,0,1), 1.35);
      r = cT[0]+(cH[0]-cT[0])*sv; g2 = cT[1]+(cH[1]-cT[1])*sv; b2 = cT[2]+(cH[2]-cT[2])*sv;
      // rolling ash cloud: two-sided — it occludes AND its base catches the fissure light
      const cf = fbm4(nx*2.7 + dk1*2.2, ny*4.6 + dk2*1.5);
      const cf2 = fbm(nx*6.1 - dk2*3.1, ny*8.0 + dk1*1.1);
      const mass = cl((cf-.40)*2.3, 0, 1)*.70 + cl((cf2-.46)*2.6, 0, 1)*.30;
      const occ = mass*.46*(1-sv*.35);
      r *= (1-occ); g2 *= (1-occ); b2 *= (1-occ);
      const litK = mass*(.30+en*.55)*sunOcc*(.30+.70*sv);
      r += (cH[0]*1.25-r)*litK*.42; g2 += (cH[1]*1.25-g2)*litK*.42; b2 += (cH[2]*1.25-b2)*litK*.42;
      // the fissure throwing dull red on the underside of the cloud
      const dfx = (nx-fissX)*1.1, dfy = (ny-hzn*.995)*2.4;
      const dfi = Math.sqrt(dfx*dfx+dfy*dfy);
      const fg = Math.exp(-dfi*2.2)*fissB*(.45+mass*.75);
      r += cF[0]*fg*.42; g2 += cF[1]*fg*.42; b2 += cF[2]*fg*.42;
      // ash actually hanging in the air near the horizon — the sky and ground share a colour
      const hzk = Math.exp(-(hzn-ny)*(4.2-fal*1.4))*(.35+fal*.55);
      r += (cHz[0]-r)*hzk*.55; g2 += (cHz[1]-g2)*hzk*.55; b2 += (cHz[2]-b2)*hzk*.55;
    } else {
      // ================= the plain =================
      const dv = (ny-hzn)/Math.max(.04,1-hzn);
      const Z = 1/Math.max(.010, dv*dv*1.7 + .010);
      const X = (nx-.5)*Z*.62;
      const det = cl(1 - Z*.028, .05, 1);
      // fresh fall: a smooth, wind-worked blanket. Ridged noise gives the sharp-crested
      // dune fabric that says "this is a powder, not soil".
      const dune = rdg(X*.34 + dz*.30, Z*.30 - dz*.14)*.6 + rdg(X*.9 - dz*.18, Z*.8+11.3)*.4;
      const grain = fbm4(X*5.5, Z*4.8 + dz*.20)*det + (1-det)*.5;
      // lahar channels: cut DOWN through the fresh fall to the old dark surface. Dendritic,
      // and the exposed floor is a different material — the only value contrast on the plain.
      const ch1 = Math.abs(fbm(X*.30+3.1, Z*.22 - dz*.02)-.5);
      const ch2 = Math.abs(fbm(X*.75-7.3, Z*.55 + 2.1)-.5);
      const chan = cl(1-ch1*11.0, 0, 1)*.7 + cl(1-ch2*15.0, 0, 1)*.42;
      const inChan = cl(chan, 0, 1);
      let lum = .34 + dune*.26 + grain*.22;
      // low raking light from the fissure side, so the dune crests catch and the lee goes dark
      const rake = cl(.5 + (nx-fissX)*1.1, 0, 1);
      lum *= .72 + rake*(.34+en*.30);
      // cloud shadow crawling the plain: the broad, always-moving area element down here.
      // Without it the ground is a still and only the falling ash moves.
      const csh = cl((fbm(X*.22 + dk1*3.4, Z*.17 + dk2*2.2)-.42)*2.3, 0, 1);
      lum *= 1 - csh*(.30+en*.20);
      lum = cl(lum, 0, 1.2);
      r = cAd[0]+(cAl[0]-cAd[0])*lum; g2 = cAd[1]+(cAl[1]-cAd[1])*lum; b2 = cAd[2]+(cAl[2]-cAd[2])*lum;
      // the channel floor: old surface, darker and cooler than the fresh fall on top
      const cc = inChan*cl(1-dv*.25,0,1);
      r += (cAd[0]*.68-r)*cc*.80; g2 += (cAd[1]*.68-g2)*cc*.80; b2 += (cAd[2]*.72-b2)*cc*.80;
      // fissure light reaching the ground near the horizon
      const fgg = Math.exp(-Math.hypot((nx-fissX)*1.3, (ny-hzn)*3.0)*2.6)*fissB*.45;
      r += cF[0]*fgg*.30; g2 += cF[1]*fgg*.30; b2 += cF[2]*fgg*.30;
      // aerial perspective: ash in the air kills the plain into the horizon
      const ha = Math.pow(cl(1-dv*2.4, 0, 1), 1.5)*(.45+fal*.42);
      r += (cHz[0]-r)*ha; g2 += (cHz[1]-g2)*ha; b2 += (cHz[2]-b2)*ha;
    }
    const o = 4*(j*BW+i);
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255); px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();

const AL = P.alpha/100;
const dens = cl(P.density,0,1);

// ---- dead standing timber: stripped trunks in ranks, buried to different depths ----
push();
const NT = Math.round(3 + dens*16);
for (let i=0;i<NT;i++){
  const f1 = fr(i*6+11), f2 = fr(i*6+12), f3 = fr(i*6+13), f4 = fr(i*6+14);
  const dep = f2;                                       // 0 far, 1 near
  const tx = ((f1*1.3 - .15) + dz*(.02 + dep*.10)) % 1.3 - .15;
  const ty = hy + Math.pow(dep,1.8)*(height-hy)*.92;
  const th = u*(.03 + Math.pow(dep,1.6)*.30)*sc*(.5+f3*.9);
  const lean = (f4-.5)*.34;
  // aerial perspective on the trunk itself
  const hk = cl((1-dep)*(1-dep)*(.45+fal*.75), 0, .92);
  const tc = [ ashD[0]+(hazeC[0]-ashD[0])*hk, ashD[1]+(hazeC[1]-ashD[1])*hk,
               ashD[2]*(.7+f3*.5)+(hazeC[2]-ashD[2]*.7)*hk ];
  stroke(tc[0], tc[1], tc[2], (72+dep*22)*AL);
  strokeWeight(Math.max(.6, th*.055*(.6+f3*.7)));
  noFill();
  // a slight sway even in dead timber — the wind is still working
  const sw = Math.sin(tt*(.19+f3*.3)+f1*6.28)*(.006+dep*.020)*(.3+en);
  line(tx*width, ty, tx*width + th*lean + sw*width, ty - th);
  // a couple of broken limbs
  if (f3 > .4){
    strokeWeight(Math.max(.5, th*.028));
    const ly = ty - th*(.55+f4*.3);
    line(tx*width + th*lean*.55, ly, tx*width + th*lean*.55 + th*(.16+f1*.2)*(f4>.5?1:-1), ly - th*.14);
  }
}
pop();

// ---- the fall itself: ash coming down everywhere, for ever. Broad coverage, and it is what
// makes the whole frame live even when the plain and the deck are momentarily quiet. ----
push();
noStroke();
const NA = Math.round(40 + dens*260);
for (let i=0;i<NA;i++){
  const f1 = fr(i*3+101), f2 = fr(i*3+102), f3 = fr(i*3+103);
  const rate = (.018 + f3*.075)*(.3+fal*1.7)*P.speed;
  // flakes tumble: a lateral wander on rates incommensurate with the fall
  const py = ((f2 + tt*rate) % 1.12) - .06;
  const pxx = ((f1 + Math.sin(tt*(.21+f3*.5)+f1*6.28)*.020
                   + Math.sin(tt*(.07+f2*.15)+f2*6.28)*.038
                   + tt*rate*.22) % 1.12) - .06;
  const near = f3;
  const sz = u*(.0012 + near*.0042)*(.6+fal*.9)*sc;
  const br = (.35 + near*.55);
  fill(ashL[0], ashL[1]*.7, ashL[2]*(.75+near*.45), (26+near*40)*br*AL);
  ellipse(pxx*width, py*height, sz, sz*(.8+f2*.5));
}
pop();

// ---- ash veils blowing across, and a dust devil or two lifting off the plain ----
push();
noStroke();
const NV = Math.round(4 + dens*7);
for (let i=0;i<NV;i++){
  const f1 = fr(i*5+201), f2 = fr(i*5+202), f3 = fr(i*5+203);
  const vx = ((f1 + tt*(.006+f2*.014)*P.speed) % 1.5 - .25)*width;
  const vy = hy + (f2-.3)*height*.34;
  fill(hazeC[0], hazeC[1]*(.7+f3*.5), hazeC[2]*(.9+f3*.3), (6+fal*12)*AL);
  ellipse(vx, vy + Math.sin(tt*(.06+f1*.13))*height*.010,
          width*(.28+f1*.5), height*(.018+f3*.06));
}
// dust devils: tall, thin, leaning columns that wander the plain
const ND = Math.round(dens*3);
for (let i=0;i<ND;i++){
  const f1 = fr(i*7+301), f2 = fr(i*7+302);
  const dx = ((f1 + tt*(.010+f2*.016)*P.speed) % 1.4 - .2)*width;
  const dyb = hy + (.06+f2*.30)*(height-hy);
  const dh = u*(.10+f2*.22)*sc;
  for (let k=0;k<9;k++){
    const q = k/9;
    const wob = Math.sin(tt*(.9+f2*1.4)+q*4.1+f1*6.28)*dh*.10*(q+.2);
    fill(hazeC[0], hazeC[1]*.8, hazeC[2]*(1+q*.3), (13*(1-q*.55))*AL);
    ellipse(dx+wob+q*dh*.22, dyb - q*dh, dh*(.06+q*.20), dh*(.06+q*.10));
  }
}
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
drawingContext.globalAlpha = 1;
